flashConversationPrompt.responseSchema:
{
  "type": "object",
  "description": "Companion conversation output — response, UI, routing, enriched query",
  "required": [
    "intent",
    "enrichedQuery"
  ],
  "properties": {
    "intent": {
      "type": "string",
      "description": "Per-turn intent signal for backend routing.",
      "enum": [
        "DATA_INPUT",
        "WHAT_IF",
        "CORRECTION",
        "QUESTION",
        "GOAL_CHANGE",
        "GOAL_QUERY",
        "GREETING",
        "ACKNOWLEDGMENT"
      ]
    },
    "enrichedQuery": {
      "type": "string",
      "description": "Contextually refined, self-contained version of the user's message. Resolves pronouns, expands implicit context, includes relevant user profile details. One to three sentences."
    },
    "thinkingText": {
      "type": "string",
      "description": "Temporary placeholder shown to the user while the Planner works. Emitted ONLY when escalation.needed = true — mutually exclusive with uiDirective. References the topic without predicting the answer. One sentence, present progressive, ends with ellipsis.",
      "nullable": true
    },
    "assistantText": {
      "type": "string",
      "description": "Execution log for chatHistory continuity — next-turn LLM reads this to know what happened structurally. MUST include: (1) components rendered as `Rendered: componentId, fields=[...]`, (2) escalation actions as `Escalated: deviationType, reason=...`, (3) goal state changes as `GoalMutation: goalRef, action, fields changed`. NOT user-facing."
    },
    "uiDirective": {
      "type": "object",
      "description": "Screen composition instruction. Null on escalation turns (thinkingText is emitted instead).",
      "nullable": true,
      "properties": {
        "components": {
          "type": "array",
          "description": "Ordered list of components to render from the palette. Typically begins with RESPONSE_TEXT, followed by additional visual components.",
          "items": {
            "type": "object",
            "required": [
              "componentId"
            ],
            "properties": {
              "componentId": {
                "type": "string",
                "description": "Component ID from the palette (e.g., 'RESPONSE_TEXT', 'RESULT_REVEAL', 'OPTION_SELECTOR')."
              },
              "entityMeta": {
                "type": "object",
                "description": "Entity context for this component. Required for input components; null for display-only components.",
                "nullable": true,
                "properties": {
                  "entityGroupId": {
                    "type": "string",
                    "description": "Entity group this component collects for (e.g., 'person_1', 'person_2', 'household_1')."
                  },
                  "relationshipToUser": {
                    "type": "string",
                    "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                    "description": "The entity's relationship to the primary user."
                  }
                }
              },
              "data": {
                "type": "string",
                "description": "The serialized JSON data payload for the component, matching the data schema defined in the palette.",
                "nullable": true
              },
              "priority": {
                "type": "number",
                "description": "Display priority (1 = highest)."
              }
            }
          }
        }
      }
    },
    "escalation": {
      "type": "object",
      "description": "Escalation signal to the Planner. Null if no escalation needed.",
      "nullable": true,
      "properties": {
        "needed": {
          "type": "boolean",
          "description": "True if this turn requires Planner involvement"
        },
        "reason": {
          "type": "string",
          "description": "Prose description of why escalation is needed and the conversational context."
        },
        "deviationType": {
          "type": "string",
          "description": "Category of deviation that triggered escalation",
          "enum": [
            "GOAL_REQUIRES_DECOMPOSITION",
            "HIGH_CONSEQUENCE_RECOMMENDATION",
            "GOAL_CHANGE",
            "UNRESOLVABLE_AMBIGUITY",
            "BEYOND_KNOWLEDGE_BASE",
            "EMOTIONAL_DISTRESS",
            "CONTRADICTION"
          ],
          "nullable": true
        },
        "goalContextFetch": {
          "type": "object",
          "description": "Instructs the backend router to fetch and hydrate enriched goal context for the specified goals before invoking the Planner. Only meaningful when needed=true.",
          "nullable": true,
          "properties": {
            "focusGoals": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Goal IDs (from T1 portfolio) that the Planner should receive enriched context for."
            },
            "tier": {
              "type": "string",
              "enum": [
                "STANDARD",
                "DEEP"
              ],
              "description": "STANDARD = Tier 1 + Tier 2. DEEP = Tier 1 + Tier 2 + Tier 3."
            }
          }
        }
      }
    },
    "goalMutation": {
      "type": "object",
      "description": "Goal update or lifecycle action for backend persistence. Null if no goal change this turn.",
      "nullable": true,
      "required": [
        "action"
      ],
      "properties": {
        "action": {
          "type": "string",
          "enum": [
            "UPDATE",
            "LIFECYCLE"
          ],
          "description": "UPDATE for field changes. LIFECYCLE for state transitions (pause, resume, abandon)."
        },
        "goalRef": {
          "type": "string",
          "description": "Goal ID from T1 portfolio being updated."
        },
        "target": {
          "type": "object",
          "nullable": true,
          "description": "§2 Target field updates. Only include changed fields.",
          "properties": {
            "amount": {
              "type": "string",
              "nullable": true,
              "description": "Target amount with ₹ prefix. E.g. '₹3,20,000'."
            },
            "horizonRaw": {
              "type": "string",
              "nullable": true,
              "description": "Freeform temporal expression. E.g. 'by 2029'."
            },
            "horizonType": {
              "type": "string",
              "enum": [
                "DATE",
                "RELATIVE",
                "MILESTONE",
                "RECURRING",
                "OPEN"
              ],
              "nullable": true
            }
          }
        },
        "plan": {
          "type": "object",
          "nullable": true,
          "description": "§4 Plan field updates. Companion reports progress here.",
          "properties": {
            "monthlyContribution": {
              "type": "string",
              "nullable": true,
              "description": "E.g. '₹5,000/month'."
            },
            "progress": {
              "type": "string",
              "nullable": true,
              "description": "Current amount saved. E.g. '₹50,000'."
            }
          }
        },
        "goalContext": {
          "type": "object",
          "nullable": true,
          "description": "§5 Goal Context updates. Companion can update reasoning state and append to memory fields.",
          "properties": {
            "confidence": {
              "type": "string",
              "enum": [
                "LOW",
                "MEDIUM",
                "HIGH"
              ],
              "nullable": true
            },
            "notes": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true
            },
            "userPreferences": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Append-only. User choices that constrain future advice."
            },
            "emotionalSignals": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Append-only. Emotional context for re-engagement tone."
            }
          }
        },
        "lifecycleAction": {
          "type": "string",
          "enum": [
            "PAUSE",
            "RESUME",
            "COMPLETE",
            "ABANDON"
          ],
          "description": "State transition. Only valid when action = LIFECYCLE.",
          "nullable": true
        },
        "lifecycleReason": {
          "type": "string",
          "nullable": true,
          "description": "Why — AI-generated summary from conversation. Required for ABANDON, optional for others."
        }
      }
    }
  }
}
